CREATE OR REPLACE FUNCTION public.campaign_has_submissions(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.submissions WHERE campaign_id=_id) $$;
REVOKE ALL ON FUNCTION public.campaign_has_submissions(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.campaign_has_submissions(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.touch_campaign() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN IF new.id IS DISTINCT FROM old.id OR new.client_id IS DISTINCT FROM old.client_id OR new.created_at IS DISTINCT FROM old.created_at THEN RAISE EXCEPTION 'Campaign ownership and identity are immutable'; END IF; IF (new.reward_rate IS DISTINCT FROM old.reward_rate OR new.reward_description IS DISTINCT FROM old.reward_description) AND public.campaign_has_submissions(old.id) THEN RAISE EXCEPTION 'Reward terms are locked once a clip has been submitted' USING ERRCODE='P0001', HINT='reward_terms_locked'; END IF; new.updated_at:=now(); RETURN new; END $$;